const { formatTitle } = require('../src/format');

test('formatTitle title-cases (AC1)', () => {
  assert.equal(formatTitle('quarterly sales'), 'Quarterly Sales');
});

test('formatTitle trims and leaves letters after an apostrophe alone', () => {
  assert.equal(formatTitle("  customer's churn "), "Customer's Churn");
});

const test = require('node:test');
const assert = require('node:assert');
const { exportCsv } = require('../src/exports');
const store = require('../src/store');
const { events } = require('../src/usage');

test('exportCsv title column is trimmed and title-cased', () => {
  const csv = exportCsv(store.all());
  assert.deepEqual(csv.split('\n'), [
    'id,title',
    'r1,Quarterly Sales',
    'r2,Churn By Region',
  ]);
});

test('exportCsv emits a report.export usage event', () => {
  const before = events.length;
  exportCsv([]);
  assert.deepEqual(
    { action: events[before].action, count: events[before].count },
    { action: 'report.export', count: 0 },
  );
});

