const test = require('node:test');
const assert = require('node:assert');
const store = require('../src/store');
const { formatTitle } = require('../src/format');
const { getReport, listReports } = require('../src/reports');
const { exportCsv } = require('../src/exports');
const { handleGetReport } = require('../src/server');

test('formatTitle trims and collapses in one pass, leaves single spaces and tabs alone', () => {
  assert.equal(formatTitle('   Churn    by  region  '), 'Churn by region');
  assert.equal(formatTitle('Churn by region'), 'Churn by region');
  assert.equal(formatTitle('a\t\tb'), 'a\t\tb');
});

test('listReports titles are trimmed exactly (every report)', () => {
  assert.deepEqual(listReports(), [
    { id: 'r1', title: 'Quarterly sales' },
    { id: 'r2', title: 'Churn by region' },
  ]);
});

test('getReport / GET /reports/:id collapse double spaces from the store', (t) => {
  t.mock.method(store, 'get', () => ({ id: 'x', title: ' Churn  by   region ', rows: 1 }));
  assert.equal(getReport('x').title, 'Churn by region');
  const res = handleGetReport('x');
  assert.equal(res.status, 200);
  assert.deepEqual(res.body, { id: 'x', title: 'Churn by region', rows: 1 });
});

test('listReports collapses double spaces for every report', (t) => {
  t.mock.method(store, 'all', () => [
    { id: 'a', title: 'A  b' },
    { id: 'b', title: ' C   d ' },
  ]);
  assert.deepEqual(listReports(), [
    { id: 'a', title: 'A b' },
    { id: 'b', title: 'C d' },
  ]);
});

test('exportCsv title column is collapsed for every row', () => {
  const csv = exportCsv([
    { id: 'r1', title: '  Quarterly   sales ' },
    { id: 'r2', title: 'Churn  by region' },
  ]);
  assert.equal(csv, 'id,title\nr1,Quarterly sales\nr2,Churn by region');
});

