const assert = require('node:assert');
const { formatTitle } = require('../src/format');

test('formatTitle strips a trailing period', () => {
  assert.equal(formatTitle('Churn.'), 'Churn');
});

test('formatTitle strips repeated trailing periods and surrounding whitespace', () => {
  assert.equal(formatTitle('  Churn.. '), 'Churn');
});

test('formatTitle keeps inner periods', () => {
  assert.equal(formatTitle('v1.2 sales'), 'v1.2 sales');
